        className: "language-java",
        children: "import java.util.HashMap;\r\nimport java.util.Map;\r\n\r\nclass LRUCache {\r\n    class Node {\r\n        int key, value;\r\n        Node prev, next;\r\n        Node(int key, int value) { this.key = key; this.value = value; }\r\n    }\r\n\r\n    private final int capacity;\r\n    private final Map<Integer, Node> map;\r\n    private final Node head, tail;\r\n\r\n    public LRUCache(int capacity) {\r\n        this.capacity = capacity;\r\n        map = new HashMap<>();\r\n        head = new Node(0, 0);\r\n        tail = new Node(0, 0);\r\n        head.next = tail;\r\n        tail.prev = head;\r\n    }\r\n\r\n    public int get(int key) {\r\n        Node node = map.get(key);\r\n        if (node == null) return -1;\r\n        remove(node);\r\n        insert(node);\r\n        return node.value;\r\n    }\r\n\r\n    public void put(int key, int value) {\r\n        if (map.containsKey(key)) {\r\n            remove(map.get(key));\r\n        }\r\n        if (map.size() == capacity) {\r\n            remove(tail.prev);\r\n        }\r\n        insert(new Node(key, value));\r\n    }\r\n\r\n    private void insert(Node node) {\r\n        map.put(node.key, node);\r\n        node.next = head.next;\r\n        node.prev = head;\r\n        head.next.prev = node;\r\n        head.next = node;\r\n    }\r\n\r\n    private void remove(Node node) {\r\n        map.remove(node.key);\r\n        node.prev.next = node.next;\r\n        node.next.prev = node.prev;\r\n    }\r\n}\r\n\r\npublic class LRUCacheDemo {\r\n    public static void main(String[] args) {\r\n        LRUCache cache = new LRUCache(2);\r\n        cache.put(1, 1);\r\n        cache.put(2, 2);\r\n        System.out.println(\"Get 1: \" + cache.get(1));    // Output: 1\r\n        cache.put(3, 3);                                  // evicts key 2\r\n        System.out.println(\"Get 2: \" + cache.get(2));    // Output: -1\r\n        cache.put(4, 4);                                  // evicts key 1\r\n        System.out.println(\"Get 1: \" + cache.get(1));    // Output: -1\r\n        System.out.println(\"Get 3: \" + cache.get(3));    // Output: 3\r\n        System.out.println(\"Get 4: \" + cache.get(4));    // Output: 4\r\n    }\r\n}\n"
